import { lazy } from 'react'

import { MethodItemCard } from '~/ui/layout/item/ItemCard'
import { VideoView } from '~/ui/parts/VideoView'
import type { CommonCardProp } from '~/ui/items/common'

import videoNormal from '../../uprightPiano/normal.mp4'
import videoSmall from '../../uprightPiano/small.mp4'
import thumbnailP from '../../uprightPiano/thumbnail.jpg'
import thumbnailM from '../../uprightPiano/thumbnail.mp4'

import { name } from './name'

const Explanation = lazy(() => import('./Explanation'));


export default function SlidingPartition(prop: CommonCardProp) {
  const { openDrawer, ...otherProp } = prop;
  
  return (
    <MethodItemCard
      id={name}
      {...otherProp}
      content={<VideoView
        videoNormal={videoNormal}
        videoSmall={videoSmall}
        thumbnailP={thumbnailP}
        thumbnailM={thumbnailM}
        />}
      title={<>スライド式パーテーション</>}
      >
      <Explanation openDrawer={openDrawer} />
    </MethodItemCard>
  )
}

